[CmdletBinding()]
param(
    [string]$InputRoot="${PSScriptRoot}\..\..\06_CONTROLLED_RERUN\OUTPUT\BENCHMARK\BENCH_20260619_FINAL01",
    [string]$OutputXlsx="${PSScriptRoot}\..\..\04_EVIDENCE\ENTREGA_MEMORIA_EXCELES_REGENERADOS\02_BENCHMARK_RENDIMIENTO_VALIDACION_DATOS_REGENERADO.xlsx"
)

Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem
$culture=[Globalization.CultureInfo]::InvariantCulture

function X([object]$Value){if($null -eq $Value){return ''};return [Security.SecurityElement]::Escape([string]$Value)}
function Col([int]$Index){$s='';$n=$Index;while($n-gt 0){$r=[int](($n-1)%26);$s=([char]([int](65+$r)))+$s;$n=[int][math]::Floor(($n-1)/26)};return $s}
function N($Value){if($null -eq $Value){return $null};if($Value -is [ValueType]){return [double]$Value};$d=0.0;if([double]::TryParse([string]$Value,[Globalization.NumberStyles]::Float,$culture,[ref]$d)){return $d};return $null}
function B($Value){if($Value -is [bool]){return[bool]$Value};return([string]$Value -match '^(?i:true|1)$')}
function Avg([object[]]$Values){$v=@($Values|Where-Object{$null -ne $_});if($v.Count -eq 0){return 0};return [double](($v|Measure-Object -Average).Average)}
function Max([object[]]$Values){$v=@($Values|Where-Object{$null -ne $_});if($v.Count -eq 0){return 0};return [double](($v|Measure-Object -Maximum).Maximum)}

function CellXml([string]$Ref,[object]$Value,[int]$Style=0){
    if($null -eq $Value){return "<c r=`"$Ref`" s=`"$Style`"/>"}
    if($Value -is [bool]){$v=if($Value){1}else{0};return "<c r=`"$Ref`" s=`"$Style`" t=`"b`"><v>$v</v></c>"}
    if($Value -is [double] -or $Value -is [int] -or $Value -is [long] -or $Value -is [decimal]){$v=([double]$Value).ToString('0.############',$culture);return "<c r=`"$Ref`" s=`"$Style`"><v>$v</v></c>"}
    $t=X $Value
    return "<c r=`"$Ref`" s=`"$Style`" t=`"inlineStr`"><is><t xml:space=`"preserve`">$t</t></is></c>"
}

function SheetXml([object[]]$Rows,[double[]]$Widths,[bool]$Drawing=$false,[bool]$Summary=$false){
    $maxCols=1;foreach($row in $Rows){$c=@($row).Count;if($c -gt $maxCols){$maxCols=$c}}
    $sb=New-Object Text.StringBuilder
    [void]$sb.AppendLine('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>')
    [void]$sb.AppendLine('<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">')
    [void]$sb.AppendLine("<dimension ref=`"A1:$(Col $maxCols)$($Rows.Count)`"/>")
    [void]$sb.AppendLine('<sheetViews><sheetView workbookViewId="0" showGridLines="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews>')
    [void]$sb.AppendLine('<sheetFormatPr defaultRowHeight="15"/>')
    if($Widths.Count -gt 0){[void]$sb.AppendLine('<cols>');for($i=0;$i -lt $Widths.Count;$i++){[void]$sb.AppendLine("<col min=`"$($i+1)`" max=`"$($i+1)`" width=`"$($Widths[$i])`" customWidth=`"1`"/>")};[void]$sb.AppendLine('</cols>')}
    [void]$sb.AppendLine('<sheetData>')
    for($r=0;$r -lt $Rows.Count;$r++){
        $rn=$r+1;$height=if($Summary -and $rn -eq 1){30}elseif($rn -eq 1){32}else{18};[void]$sb.Append("<row r=`"$rn`" ht=`"$height`" customHeight=`"1`">")
        $cells=@($Rows[$r]);for($c=0;$c -lt $cells.Count;$c++){
            $value=$cells[$c];$style=0
            if($r -eq 0){$style=if($Summary){6}else{1}}
            elseif($value -is [double] -or $value -is [decimal]){$style=2}
            elseif($value -is [int] -or $value -is [long]){$style=3}
            elseif([string]$value -match 'WARN'){$style=4}
            elseif([string]$value -match '^(VALID|TRUE|APTO|OK|APTO CON OBSERVACIONES)$'){$style=5}
            [void]$sb.Append((CellXml "$(Col($c+1))$rn" $value $style))
        };[void]$sb.AppendLine('</row>')
    }
    [void]$sb.AppendLine('</sheetData>')
    if(-not $Summary){[void]$sb.AppendLine("<autoFilter ref=`"A1:$(Col $maxCols)$($Rows.Count)`"/>")}
    if($Drawing){[void]$sb.AppendLine('<drawing r:id="rId1"/>')}
    [void]$sb.AppendLine('</worksheet>');return $sb.ToString()
}

function AddText($Zip,[string]$Name,[string]$Text){$e=$Zip.CreateEntry($Name);$s=$e.Open();$w=New-Object IO.StreamWriter($s,(New-Object Text.UTF8Encoding($false)));try{$w.Write($Text)}finally{$w.Dispose();$s.Dispose()}}
function NumCache([double[]]$Values){$sb=New-Object Text.StringBuilder;[void]$sb.Append("<c:numCache><c:formatCode>0.00</c:formatCode><c:ptCount val=`"$($Values.Count)`"/>");for($i=0;$i -lt $Values.Count;$i++){[void]$sb.Append("<c:pt idx=`"$i`"><c:v>$($Values[$i].ToString('0.############',$culture))</c:v></c:pt>")};[void]$sb.Append('</c:numCache>');return $sb.ToString()}
function StrCache([string[]]$Values){$sb=New-Object Text.StringBuilder;[void]$sb.Append("<c:strCache><c:ptCount val=`"$($Values.Count)`"/>");for($i=0;$i -lt $Values.Count;$i++){[void]$sb.Append("<c:pt idx=`"$i`"><c:v>$(X $Values[$i])</c:v></c:pt>")};[void]$sb.Append('</c:strCache>');return $sb.ToString()}
function ChartXml([string]$Title,[string[]]$Categories,[string]$CategoryFormula,[object[]]$Series,[int]$ChartNo){
    $catFormula=$CategoryFormula;$catCache=StrCache $Categories;$serXml=New-Object Text.StringBuilder
    for($i=0;$i -lt $Series.Count;$i++){$s=$Series[$i];$idx=$i;[void]$serXml.Append("<c:ser><c:idx val=`"$idx`"/><c:order val=`"$idx`"/><c:tx><c:v>$(X $s.Name)</c:v></c:tx><c:cat><c:strRef><c:f>$catFormula</c:f>$catCache</c:strRef></c:cat><c:val><c:numRef><c:f>$(X $s.Formula)</c:f>$(NumCache $s.Values)</c:numRef></c:val></c:ser>")}
    $ax1=100000+$ChartNo*2;$ax2=$ax1+1
    return @"
<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><c:chart><c:title><c:tx><c:rich><a:bodyPr/><a:lstStyle/><a:p><a:r><a:rPr lang="es-ES" sz="1200" b="1"/><a:t>$(X $Title)</a:t></a:r></a:p></c:rich></c:tx><c:layout/><c:overlay val="0"/></c:title><c:plotArea><c:layout/><c:barChart><c:barDir val="col"/><c:grouping val="clustered"/><c:varyColors val="0"/>$($serXml.ToString())<c:axId val="$ax1"/><c:axId val="$ax2"/></c:barChart><c:catAx><c:axId val="$ax1"/><c:scaling><c:orientation val="minMax"/></c:scaling><c:delete val="0"/><c:axPos val="b"/><c:tickLblPos val="nextTo"/><c:crossAx val="$ax2"/><c:crosses val="autoZero"/><c:auto val="1"/><c:lblAlgn val="ctr"/><c:lblOffset val="100"/></c:catAx><c:valAx><c:axId val="$ax2"/><c:scaling><c:orientation val="minMax"/></c:scaling><c:delete val="0"/><c:axPos val="l"/><c:numFmt formatCode="0.00" sourceLinked="0"/><c:majorGridlines/><c:tickLblPos val="nextTo"/><c:crossAx val="$ax1"/><c:crosses val="autoZero"/><c:crossBetween val="between"/></c:valAx></c:plotArea><c:legend><c:legendPos val="b"/><c:layout/><c:overlay val="0"/></c:legend><c:plotVisOnly val="1"/><c:dispBlanksAs val="zero"/></c:chart></c:chartSpace>
"@
}

$root=[IO.Path]::GetFullPath($InputRoot);$out=[IO.Path]::GetFullPath($OutputXlsx)
if(-not(Test-Path -LiteralPath $root -PathType Container)){throw "InputRoot ausente: $root"};if(Test-Path -LiteralPath $out){throw "Salida existente: $out"};[IO.Directory]::CreateDirectory((Split-Path -Parent $out))|Out-Null
$summaries=@(Get-ChildItem -LiteralPath $root -Recurse -Filter summary.json -File|Sort-Object FullName);if($summaries.Count -ne 9){throw "summary.json esperados=9 actual=$($summaries.Count)"}
$runs=New-Object Collections.ArrayList;$samples=New-Object Collections.ArrayList;$procs=New-Object Collections.ArrayList;$trace=New-Object Collections.ArrayList
$required=@('summary.json','samples.csv','process_samples.csv','summary.txt','process_list_start.txt','process_list_end.txt','environment.txt')
foreach($sf in $summaries){$j=Get-Content -LiteralPath $sf.FullName -Raw -Encoding UTF8|ConvertFrom-Json;$rel=$sf.FullName.Substring($root.Length).TrimStart([char]92);$p=$rel.Split([char]92);$rep=$p[0];$sc=[string]$j.Scenario;if([string]$j.SchemaVersion -ne '1.1' -or [string]$j.ScenarioValidity -ne 'VALID'){throw "$rep/$sc no válido"};$dir=$sf.Directory.FullName;$pp=Join-Path $dir 'process_samples.csv';$sp=Join-Path $dir 'samples.csv';$pr=@(Import-Csv -LiteralPath $pp);$sa=@(Import-Csv -LiteralPath $sp);$notepad=@($pr|Where-Object{[string]$_.ProcessName -match '^(?i:notepad)(\.exe)?$' -or [string]$_.Role -match '(?i)notepad'}).Count;$client=@($pr|Where-Object Role -eq 'CLIENT_SERVICE').Count;$server=@($pr|Where-Object Role -eq 'SERVER_GUI').Count;$other=@($pr|Where-Object Role -eq 'OTHER_VELOCIRAPTOR').Count
    [void]$runs.Add([pscustomobject]@{Rep=$rep;Scenario=$sc;RunId=[string]$j.RunId;Schema=[string]$j.SchemaVersion;Validity=[string]$j.ScenarioValidity;Samples=[int]$j.Samples;ClientMax=[int]$j.VR_Client_ProcessCountMax;AvgCPU=[double]$j.Avg_VR_Client_CPU_Percent;MaxCPU=[double]$j.Max_VR_Client_CPU_Percent;P95CPU=[double]$j.P95_VR_Client_CPU_Percent;AvgRAM=[double]$j.Avg_VR_Client_RAM_MB;MaxRAM=[double]$j.Max_VR_Client_RAM_MB;P95RAM=[double]$j.P95_VR_Client_RAM_MB;RunnerSamples=[int]$j.RunnerObservedSamples;StatusStart=[string]$j.ClientServiceStatusStart;StatusEnd=[string]$j.ClientServiceStatusEnd;ServerExcluded=[bool]$j.ServerGuiExcludedFromClientMetrics;IncludeServer=[bool]$j.IncludeServerGuiInTotal;Notepad=$notepad;NotepadOK=($notepad -eq 0);RunnerStill=[bool]$j.RunnerStillRunningAtEnd;StatusFlag=$(if([bool]$j.RunnerStillRunningAtEnd){'WARN'}else{'OK'});SummaryRel=$rel;SummaryHash=(Get-FileHash -LiteralPath $sf.FullName -Algorithm SHA256).Hash;Warnings=(@($j.Warnings)-join'; ');ClientRows=$client;ServerRows=$server;OtherRows=$other;ActualDuration=[double]$j.ActualDurationSec})
    foreach($r in $sa){[void]$samples.Add(@($rep,$sc,[string]$r.RunId,[string]$r.Timestamp,(N $r.ElapsedSec),[string]$r.ServiceStatus,(N $r.VR_Client_ProcessCount),(N $r.VR_Client_CPU_Percent),(N $r.VR_Client_RAM_MB),(N $r.VR_ServerGUI_ProcessCount),(N $r.VR_ServerGUI_CPU_Percent),(N $r.VR_ServerGUI_RAM_MB),(B $r.RunnerActive)))}
    foreach($r in $pr){[void]$procs.Add(@($rep,$sc,[string]$r.RunId,[string]$r.Timestamp,(N $r.ElapsedSec),[string]$r.ServiceStatus,(N $r.PID),[string]$r.Role,[string]$r.ProcessName,[string]$r.ExecutablePath,[string]$r.CommandLine,(N $r.CPU_Percent),(N $r.RAM_MB),(N $r.IO_Total_BytesSec),(B $r.RunnerActive),([string]$r.Role -eq 'CLIENT_SERVICE')))}
    foreach($name in $required){$path=Join-Path $dir $name;if(-not(Test-Path -LiteralPath $path)){throw "Falta $rep/$sc/$name"};$it=Get-Item -LiteralPath $path;[void]$trace.Add(@($rep,$sc,$name,$path.Substring($root.Length).TrimStart([char]92),[long]$it.Length,(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash))}
}
foreach($sc in @('BASELINE_NO_VR','VR_IDLE','VR_TEC_RUNNER')){if(@($runs|Where-Object Scenario -eq $sc).Count -ne 3){throw "$sc no tiene 3 runs"}}
$clientTotal=($runs.ClientRows|Measure-Object -Sum).Sum;$notepadTotal=($runs.Notepad|Measure-Object -Sum).Sum
$scenarioRows=New-Object Collections.ArrayList;[void]$scenarioRows.Add(@('Scenario','Repetitions','VALID runs','Avg CPU cliente (%)','Max CPU cliente (%)','Avg RAM cliente (MB)','Max RAM cliente (MB)','VR_Client_ProcessCountMax','RunnerObservedSamples total','RunnerStillRunning WARN'))
foreach($sc in @('BASELINE_NO_VR','VR_IDLE','VR_TEC_RUNNER')){$g=@($runs|Where-Object Scenario -eq $sc);[void]$scenarioRows.Add(@($sc,$g.Count,@($g|Where-Object Validity -eq 'VALID').Count,(Avg $g.AvgCPU),(Max $g.MaxCPU),(Avg $g.AvgRAM),(Max $g.MaxRAM),(Max $g.ClientMax),($g.RunnerSamples|Measure-Object -Sum).Sum,@($g|Where-Object RunnerStill -eq $true).Count))}
$invalidClientRuns=@($runs|Where-Object {
    $clientOk=if($_.Scenario -eq 'BASELINE_NO_VR'){$_.ClientMax -eq 0}else{$_.ClientMax -gt 0}
    $serviceOk=if($_.Scenario -eq 'BASELINE_NO_VR'){$_.StatusEnd -eq 'Stopped'}else{$_.StatusEnd -eq 'Running'}
    $runnerOk=if($_.Scenario -eq 'VR_TEC_RUNNER'){$_.RunnerSamples -gt 0}else{$true}
    -not ($_.Schema -eq '1.1' -and $_.Validity -eq 'VALID' -and $clientOk -and $serviceOk -and $_.ServerExcluded -and -not $_.IncludeServer -and $_.NotepadOK -and $runnerOk)
})
$globalValid=($invalidClientRuns.Count -eq 0)
if(-not $globalValid){throw "Benchmark no válido para cliente: $($invalidClientRuns.Count) runs incumplen controles bloqueantes"}
$summaryRows=@(@('Benchmark Velociraptor BENCH_20260619_FINAL01','Valor','Interpretación'),@('Estado global','APTO CON OBSERVACIONES','9 runs válidos; 3 WARN no bloqueantes'),@('Runs VALID',9,'3 por escenario'),@('SchemaVersion 1.1',9,'9/9'),@('ClientRows',[int]$clientTotal,'CLIENT_SERVICE real'),@('ValidForClientBenchmark',$globalValid,'Todos los controles bloqueantes pasan'),@('notepad.exe clasificado como runner',[int]$notepadTotal,'Debe ser 0'),@('SERVER_GUI excluido',9,'ServerGuiExcluded=true e IncludeServer=false'),@('RunnerStillRunningAtEnd WARN',@($runs|Where-Object RunnerStill -eq $true).Count,'WARN, no invalida'),@('Samples totales',[int]$samples.Count,'samples.csv'),@('Process samples totales',[int]$procs.Count,'process_samples.csv'),@('Conclusión CPU/RAM','CLIENT_SERVICE únicamente','SERVER_GUI solo trazabilidad'))
$runRows=New-Object Collections.ArrayList;[void]$runRows.Add(@('Repetition','Scenario','RunId','SchemaVersion','ScenarioValidity','Samples','VR_Client_ProcessCountMax','Avg_VR_Client_CPU_Percent','Max_VR_Client_CPU_Percent','P95_VR_Client_CPU_Percent','Avg_VR_Client_RAM_MB','Max_VR_Client_RAM_MB','P95_VR_Client_RAM_MB','RunnerObservedSamples','ClientServiceStatusStart','ClientServiceStatusEnd','SERVER_GUI_Excluded','Include_SERVER_GUI_In_Total','NotepadRows','NotepadNoRunner','RunnerStillRunningAtEnd','StatusFlag','Warnings','ClientRows','ServerGuiRows','OtherVelociraptorRows','ActualDurationSec','SummaryRelativePath','SummarySHA256'))
foreach($r in $runs){[void]$runRows.Add(@($r.Rep,$r.Scenario,$r.RunId,$r.Schema,$r.Validity,$r.Samples,$r.ClientMax,$r.AvgCPU,$r.MaxCPU,$r.P95CPU,$r.AvgRAM,$r.MaxRAM,$r.P95RAM,$r.RunnerSamples,$r.StatusStart,$r.StatusEnd,$r.ServerExcluded,$r.IncludeServer,$r.Notepad,$r.NotepadOK,$r.RunnerStill,$r.StatusFlag,$r.Warnings,$r.ClientRows,$r.ServerRows,$r.OtherRows,$r.ActualDuration,$r.SummaryRel,$r.SummaryHash))}
$quality=New-Object Collections.ArrayList;[void]$quality.Add(@('Repetition','Scenario','Schema 1.1','Scenario VALID','Client criterion','ServiceStatusEnd','SERVER_GUI excluded','notepad no runner','Runner observed','ValidForClientBenchmark','Observation'))
foreach($r in $runs){$clientOk=if($r.Scenario -eq 'BASELINE_NO_VR'){$r.ClientMax -eq 0}else{$r.ClientMax -gt 0};$serviceOk=if($r.Scenario -eq 'BASELINE_NO_VR'){$r.StatusEnd -eq 'Stopped'}else{$r.StatusEnd -eq 'Running'};$runnerOk=if($r.Scenario -eq 'VR_TEC_RUNNER'){$r.RunnerSamples -gt 0}else{$true};$valid=($r.Schema -eq '1.1' -and $r.Validity -eq 'VALID' -and $clientOk -and $serviceOk -and $r.ServerExcluded -and -not $r.IncludeServer -and $r.NotepadOK -and $runnerOk);[void]$quality.Add(@($r.Rep,$r.Scenario,$r.Schema -eq '1.1',$r.Validity -eq 'VALID',$clientOk,$serviceOk,($r.ServerExcluded -and -not $r.IncludeServer),$r.NotepadOK,$runnerOk,$valid,$(if($r.RunnerStill){'WARN: runner activo al final; muestra válida'}else{'OK'})))}
$sampleData=New-Object Collections.ArrayList;[void]$sampleData.Add(@('Repetition','Scenario','RunId','Timestamp','ElapsedSec','ServiceStatus','VR_Client_ProcessCount','VR_Client_CPU_Percent','VR_Client_RAM_MB','VR_ServerGUI_ProcessCount','VR_ServerGUI_CPU_Percent','VR_ServerGUI_RAM_MB','RunnerActive'));foreach($r in $samples){[void]$sampleData.Add($r)}
$procData=New-Object Collections.ArrayList;[void]$procData.Add(@('Repetition','Scenario','RunId','Timestamp','ElapsedSec','ServiceStatus','PID','Role','ProcessName','ExecutablePath','CommandLine','CPU_Percent','RAM_MB','IO_Total_BytesSec','RunnerActive','IncludedInClientMetrics'));foreach($r in $procs){[void]$procData.Add($r)}
$traceData=New-Object Collections.ArrayList;[void]$traceData.Add(@('Repetition','Scenario','FileType','RelativePath','LengthBytes','SHA256'));foreach($r in $trace){[void]$traceData.Add($r)}
$method=@(@('Elemento','Criterio aplicado'),@('Fuente','Exclusivamente BENCH_20260619_FINAL01; no se usa el Excel antiguo.'),@('Diseño','3 repeticiones x 3 escenarios.'),@('Validez','SchemaVersion 1.1 y ScenarioValidity VALID en 9/9.'),@('Cliente','CPU/RAM solo CLIENT_SERVICE.'),@('SERVER_GUI','Conservado en raw y excluido del total cliente.'),@('notepad.exe','0 filas clasificadas como runner.'),@('Runner','RunnerObservedSamples > 0 en VR_TEC_RUNNER.'),@('WARN','RunnerStillRunningAtEnd=True se informa y no invalida.'),@('Trazabilidad','SHA-256 de 7 ficheros por run.'))
$runnerByRep=@{}
foreach($rep in @('REP_01','REP_02','REP_03')){$runnerByRep[$rep]=[int](@($runs|Where-Object {$_.Rep -eq $rep -and $_.Scenario -eq 'VR_TEC_RUNNER'})[0].RunnerSamples)}
$graphRows=@(@('Scenario','Avg CPU %','Max CPU %','Avg RAM MB','Max RAM MB','Client Process Max'),@($scenarioRows[1][0],$scenarioRows[1][3],$scenarioRows[1][4],$scenarioRows[1][5],$scenarioRows[1][6],$scenarioRows[1][7]),@($scenarioRows[2][0],$scenarioRows[2][3],$scenarioRows[2][4],$scenarioRows[2][5],$scenarioRows[2][6],$scenarioRows[2][7]),@($scenarioRows[3][0],$scenarioRows[3][3],$scenarioRows[3][4],$scenarioRows[3][5],$scenarioRows[3][6],$scenarioRows[3][7]),@('REP_01 RunnerSamples',$runnerByRep['REP_01']),@('REP_02 RunnerSamples',$runnerByRep['REP_02']),@('REP_03 RunnerSamples',$runnerByRep['REP_03']))
$sheets=@(
 [pscustomobject]@{Name='RESUMEN_EJECUTIVO';Rows=$summaryRows;Widths=@(42,28,70);Summary=$true;Drawing=$false},
 [pscustomobject]@{Name='RUNS_9';Rows=$runRows.ToArray();Widths=@(12,20,33,14,16,10,18,16,16,16,18,18,18,20,18,18,19,22,13,18,22,12,55,13,15,20,16,75,68);Summary=$false;Drawing=$false},
 [pscustomobject]@{Name='RESUMEN_ESCENARIO';Rows=$scenarioRows.ToArray();Widths=@(22,13,13,20,20,22,22,24,25,25);Summary=$false;Drawing=$false},
