 [pscustomobject]@{Name='PROCESS_SAMPLES';Rows=$procData.ToArray();Widths=@(12,20,33,29,12,16,10,22,25,58,85,14,14,20,14,24);Summary=$false;Drawing=$false},
 [pscustomobject]@{Name='TRAZABILIDAD';Rows=$traceData.ToArray();Widths=@(12,20,24,90,16,68);Summary=$false;Drawing=$false},
