$fs=[IO.File]::Open($out,[IO.FileMode]::CreateNew);$zip=New-Object IO.Compression.ZipArchive($fs,[IO.Compression.ZipArchiveMode]::Create)
try{
 $ct=New-Object Text.StringBuilder;[void]$ct.AppendLine('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>');[void]$ct.AppendLine('<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/><Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/><Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/>');for($i=1;$i -le $sheets.Count;$i++){[void]$ct.AppendLine("<Override PartName=`"/xl/worksheets/sheet$i.xml`" ContentType=`"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml`"/>")};[void]$ct.AppendLine('<Override PartName="/xl/drawings/drawing1.xml" ContentType="application/vnd.openxmlformats-officedocument.drawing+xml"/>');for($i=1;$i -le 4;$i++){[void]$ct.AppendLine("<Override PartName=`"/xl/charts/chart$i.xml`" ContentType=`"application/vnd.openxmlformats-officedocument.drawingml.chart+xml`"/>")};[void]$ct.AppendLine('</Types>');AddText $zip '[Content_Types].xml' $ct.ToString()
